mapper.select:
with a as (select contract_code, product_code, manage_user_code, sum(task_num) task_num ,BOOL_OR(report_show) report_show from ${dynamicTableNameProxy.collaborateProduceDistribute} a where contract_code =#{cid}
and product_code in
#{id.did}
and manage_user_code =${dynamicTableNameProxy.currentCode} group by contract_code, product_code, manage_user_code) , b as (select contract_code, product_code, b.operation_user_code, sum(b.finish_num) finish_num from ${dynamicTableNameProxy.collaborateProduceResult} b where contract_code =#{cid}
and product_code in
#{id.did}
and operation_user_code =${dynamicTableNameProxy.currentCode} group by contract_code, product_code, b.operation_user_code)
select a.contract_code, a.product_code, a.manage_user_code, coalesce(a.task_num,0) task_num , coalesce(b.finish_num,0) finish_num , coalesce(a.report_show ,false) report_show from a left join b on a.contract_code = b.contract_code and a.product_code = b.product_code and a.manage_user_code = b.operation_user_code

select coalesce(sum(order_quantity), 0) task_num
from ${dynamicTableNameProxy.collaborateScheduleItem}
where collaborate_type = 0
  and delete_flag = false
  and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
  and can_produce = true


    and create_time >= #{data.startTime}




    and create_time <= #{data.endTime}

select coalesce(sum(finish_num), 0) finish_num
from ${dynamicTableNameProxy.collaborateProduceResult}
where report_status in (1, 2)
  and delete_flag = false
  and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}


    and create_time >= #{data.startTime}




    and create_time <= #{data.endTime}

with a as (

select coalesce(sum(finish_num), 0) finish_num, product_code
from ${dynamicTableNameProxy.collaborateProduceResult}
where report_status in (1, 2)
and delete_flag = false
and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
and contract_code = #{contractCode}
group by product_code


),

b as (

select coalesce(sum(task_num), 0) task_num ,product_code
from (select batch_global_code, product_code, min(task_num) task_num
from ${dynamicTableNameProxy.collaborateProduceDistribute} ptdmcpd
where delete_flag = false
and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
and contract_code = #{contractCode}
group by batch_global_code, product_code) group by product_code
)
select b.task_num , a.finish_num, b.product_code from b left join a on a.product_code=b.product_code
where b.task_num > coalesce( a.finish_num,0)

select coalesce(sum(finish_num), 0) finish_num, product_code
from ${dynamicTableNameProxy.collaborateProduceResult}
where report_status in (1, 2)
  and delete_flag = false
  and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
  and contract_code = #{contractCode}
group by product_code

select coalesce(sum(task_num), 0) task_num
from (select batch_global_code, product_code, min(task_num) task_num
from ${dynamicTableNameProxy.collaborateProduceDistribute} ptdmcpd
where delete_flag = false
and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}


    and create_time >= #{data.startTime}




    and create_time <= #{data.endTime}



group by batch_global_code, product_code)

with a as (select product_code, sum(finish_num) finish_num, contract_code
           from ${dynamicTableNameProxy.collaborateProduceResult}
           where report_status in (1, 2)
             and delete_flag = false
             and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
             and contract_code = #{contractCode}
             and product_code = #{productCode}
           group by product_code, contract_code),

     c as (select coalesce(sum(task_num), 0) task_num, product_code, contract_code
           from (select batch_global_code, product_code, min(task_num) task_num, contract_code
                 from ${dynamicTableNameProxy.collaborateProduceDistribute}
                 where delete_flag = false
                   and delete_flag = false
                   and contract_code = #{contractCode}
                   and product_code = #{productCode}
                   and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
                 group by batch_global_code, product_code, contract_code)
           group by product_code, contract_code)

select b.collaborate_material    product_code,
       coalesce(a.finish_num, 0) finish_num,
       b.order_quantity,
       b.schedule_quantity,
       c.task_num,
       b.primary_key
from ${dynamicTableNameProxy.collaborateScheduleItem} b

         join c on b.collaborate_material = c.product_code and c.contract_code = b.contract_code
         left join a on a.product_code = b.collaborate_material and b.contract_code = a.contract_code
where b.delete_flag = false
  and b.enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
  and b.contract_code = #{contractCode}
  and b.collaborate_type = 0
  and b.collaborate_material = #{productCode}
